<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/config/product_step12.php';
if (empty($_SESSION['product_sales_csrf'])) $_SESSION['product_sales_csrf']=bin2hex(random_bytes(24));
$csrf=(string)$_SESSION['product_sales_csrf'];
$error=null;$success=null;$quotes=[];$members=[];$selected=null;$ctx=[];
$quoteId=(int)($_GET['quote']??$_POST['quote_id']??0);
try{
    $pdo=business_db();product_step12_ensure($pdo);$ctx=product_step12_context($pdo);$orgId=(int)$ctx['organization_id'];
    if($_SERVER['REQUEST_METHOD']==='POST'){
        if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');
        $memberRaw=trim((string)($_POST['member_id']??''));$memberId=$memberRaw===''?null:(int)$memberRaw;
        if($memberRaw!==''&&$memberId<=0)throw new RuntimeException('Choose a valid member or leave member link empty.');
        $orderDate=(string)($_POST['order_date']??date('Y-m-d'));
        $orderId=product_step12_finalize_quote($pdo,$quoteId,$memberId,$orderDate);
        header('Location: product_sales_center.php?quote='.$quoteId.'&order='.$orderId.'&saved=1');exit;
    }
    $stmt=$pdo->prepare("SELECT q.id,q.quote_code,q.customer_name,q.customer_type,q.pricing_tier_code,q.grand_total,q.total_vp,q.status,q.created_at,l.order_id,m.full_name member_name
        FROM product_quotes q
        LEFT JOIN product_quote_order_links l ON l.organization_id=q.organization_id AND l.quote_id=q.id
        LEFT JOIN orders o ON o.id=l.order_id AND o.organization_id=q.organization_id
        LEFT JOIN members m ON m.id=o.member_id AND m.organization_id=o.organization_id
        WHERE q.organization_id=? ORDER BY q.id DESC LIMIT 100");
    $stmt->execute([$orgId]);$quotes=$stmt->fetchAll();$members=product_step12_members($pdo,$orgId);
    if($quoteId>0)$selected=product_step12_quote($pdo,$orgId,$quoteId);
    if(isset($_GET['saved']))$success='Product quote finalized into Business OS Order #'.(int)($_GET['order']??0).'.';
}catch(Throwable $e){$error=$e->getMessage();}
function ps_money(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?>
